'34\' y=\'8\' width=\'2\' height=\'1\'/%3E%3Crect x=\'36\' y=\'8\' width=\'2\' height=\'1\'/%3E%3Crect x=\'38\' y=\'8\' width=\'2\' height=\'1\'/%3E%3Crect x=\'40\' y=\'8\' width=\'2\' height=\'1\'/%3E%3Crect x=\'42\' y=\'8\' width=\'2\' height=\'1\'/%3E%3Crect x=\'44\' y=\'8\' width=\'2\' height=\'1\'/%3E%3Crect x=\'46\' y=\'8\' width=\'2\' height=\'1\'/%3E%3Crect x=\'48\' y=\'8\' width=\'2\' height=\'1\'/%3E%3Crect x=\'50\' y=\'8\' width=\'2\' height=\'1\'/%3E%3Crect x=\'52\' y=\'8\' width=\'2\' height=\'1\'/%3E%3Crect x=\'54\' y=\'8\' width=\'2\' height=\'1\'/%3E%3Crect x=\'56\' y=\'7\' width=\'2\' height=\'1\'/%3E%3Crect x=\'58\' y=\'6\' width=\'2\' height=\'1\'/%3E%3Crect x=\'60\' y=\'6\' width=\'2\' height=\'1\'/%3E%3Crect x=\'62\' y=\'5\' width=\'2\' height=\'1\'/%3E%3Crect x=\'64\' y=\'5\' width=\'2\' height=\'1\'/%3E%3Crect x=\'66\' y=\'4\' width=\'2\' height=\'1\'/%3E%3Crect x=\'68\' y=\'4\' width=\'2\' height=\'1\'/%3E%3Crect x=\'70\' y=\'4\' width=\'2\' height=\'1\'/%3E%3Crect x=\'72\' y=\'4\' width=\'2\' height=\'1\'/%3E%3Crect x=\'74\' y=\'4\' width=\'2\' height=\'1\'/%3E%3Crect x=\'76\' y=\'5\' width=\'2\' height=\'1\'/%3E%3Crect x=\'78\' y=\'5\' width=\'2\' height=\'1\'/%3E%3Crect x=\'80\' y=\'6\' width=\'2\' height=\'1\'/%3E%3Crect x=\'82\' y=\'7\' width=\'2\' height=\'1\'/%3E%3Crect x=\'84\' y=\'8\' width=\'2\' height=\'1\'/%3E%3Crect x=\'86\' y=\'10\' width=\'2\' height=\'1\'/%3E%3Crect x=\'88\' y=\'11\' width=\'2\' height=\'1\'/%3E%3Crect x=\'90\' y=\'11\' width=\'2\' height=\'1\'/%3E%3Crect x=\'92\' y=\'12\' width=\'2\' height=\'1\'/%3E%3Crect x=\'94\' y=\'13\' width=\'2\' height=\'1\'/%3E%3Crect x=\'96\' y=\'13\' width=\'2\' height=\'1\'/%3E%3C/g%3E%3C/svg%3E") 0 100%/100% 100% no-repeat}\n.yt-grass{display:none}\n.yt-laptop{position:relative;z-index:1;width:62%;display:flex;flex-direction:column;align-items:center}\n.yt-lid{width:100%;padding:8px 8px 12px;box-sizing:border-box;background:#3a1f17;box-shadow:0 0 0 3px #2b1520,6px 6px 0 #5e2f1840}\n.yt-screen{aspect-ratio:16/10;background:#fffaf0;display:flex;flex-direction:column;gap:7%;padding:5% 6%;box-sizing:border-box;overflow:hidden}\n.yt-nav{display:flex;align-items:center;gap:6px;font-family:var(--font-pixel);font-size:15px;line-height:1;color:#2b1520}\n.yt-nav b{font-weight:400;letter-spacing:.04em}.yt-logo svg{display:block;width:20px;height:14px}\n.yt-nav i{height:4px;width:12%;background:#2b152040;margin-left:6%}.yt-nav i+i{margin-left:0}.yt-nav i.r{margin-left:auto;width:16%;height:8px;background:#ff0000}\n.yt-hero{flex:1;position:relative;background:#2b1520;display:grid;place-items:center;box-shadow:inset 0 0 0 3px #3e2a22}\n.yt-play svg{display:block;width:40px;height:28px;transition:scale .2s steps(2)}\n.workcard:hover .yt-play svg{scale:1.18}\n.yt-cap{position:absolute;left:7%;bottom:12%;width:40%;display:flex;flex-direction:column;gap:4px}.yt-cap i{height:4px;background:#fffaf0cc}.yt-cap i+i{width:60%;background:#fffaf066}\n.yt-roles{display:grid;grid-template-columns:repeat(3,1fr);gap:6%;height:18%}\n.yt-roles span{background:#fff;box-shadow:0 0 0 2px #2b152022;display:flex;flex-direction:column;gap:3px;padding:4px}\n.yt-roles em{height:4px;width:70%;background:#ff0000}.yt-roles em{background:#4285f4!important}.yt-roles span:nth-child(2) em{background:#fbbc04!important}.yt-roles span:nth-child(3) em{background:#34a853!important}\n.yt-roles i{height:3px;width:90%;background:#2b152030}\n.yt-base{width:116%;height:10px;background:#5e2f18;box-shadow:0 0 0 3px #2b1520,6px 6px 0 #5e2f1840}\n.yt-note{position:absolute;z-index:2;padding:9px 10px 7px;background:var(--c);rotate:var(--r);font-family:var(--font-pixel);font-size:18px;line-height:18px;color:#3a1f17;letter-spacing:.03em;white-space:nowrap;box-shadow:0 0 0 2px #3a1f17,3px 3px 0 #3a1f1740;transition:translate .2s steps(2) var(--d,0s)}\n.yt-note:before{content:"";position:absolute;left:50%;top:-5px;width:8px;height:8px;margin-left:-4px;background:#ea4335;box-shadow:0 0 0 2px #3a1f17,inset -2px -2px 0 #b3261e}\n.workcard:hover .yt-note{translate:0 -5px}\n.yt-sign{position:absolute;left:50%;top:22px;translate:-50% 0;rotate:-3deg;z-index:3;transform-origin:50% -24px;transition:rotate .3s steps(4)}\n.workcard:hover .yt-sign{rotate:2deg}\n.yt-sign i{position:absolute;top:-24px;width:3px;height:26px;background:#5e2f18}.yt-sign i:first-child{left:20%}.yt-sign i:nth-child(2){right:20%}\n.yt-sign span{display:block;padding:7px 16px 5px;background:#a0522a repeating-linear-gradient(0deg,transparent 0 9px,#5e2f1840 9px 11px);color:#fdf1d3;font-family:var(--font-pixel);font-size:22px;line-height:22px;letter-spacing:.06em;text-transform:uppercase;white-space:nowrap;box-shadow:0 0 0 3px #3a1f17,4px 4px 0 #3a1f1740}\n@media (max-width:520px){.yt-note{font-size:12px;line-height:12px;padding:5px 6px 3px;box-shadow:0 0 0 2px #3a1f17,2px 2px 0 #3a1f1740}.yt-note:before{width:6px;height:6px;margin-left:-3px;top:-4px}.yt-laptop{width:70%}}\n@media (prefers-reduced-motion:reduce){.yt-note,.yt-sign,.yt-play svg{transition:none}}\n'
CSS += '\n/* Works cards: every card matches the tallest one, whatever its text length */\n@media (min-width:760px){\n#work > div:has(> .workcard){display:grid!important;grid-auto-rows:1fr}\n#work .workcard > .cardlink{flex:1;grid-auto-rows:auto 1fr}\n#work .workcard > .cardlink > div:last-child{justify-content:center}\n#work .workcard > .cardlink > div:last-child > div:last-child{margin-top:6px!important}\n}\n'

def apply(tpl):
    tpl, n = re.subn(r'<img aria-hidden="true" alt="" src="assets/images/sticker-triceratops-', '<img class="wc-sticker" aria-hidden="true" alt="" src="assets/images/sticker-triceratops-', tpl)
    assert n == 4, n
    start = tpl.index('<div style="position: relative; margin: 12px; min-height: 260px; border-radius: var(--radius-md); background: radial-gradient(circle at 50% 48%')
    end = tpl.index('<div style="padding: 24px 28px 28px;', start)
    end = tpl.rindex('          </div>\n', start, end)
    tpl = tpl[:start] + LC_CARD + '\n' + tpl[end + len('          </div>\n'):]
    anchor = '      </article></div>\n    </section>'
    if 'wc-soon' not in tpl and anchor in tpl:
        tpl = tpl.replace(anchor, '      </article>' + GOOGLE_CARD + '</div>\n    </section>', 1)
    return tpl
